class Solution:
    def isMonotonic(self, A: List[int]) -> bool:
        inc = dec = True
        fin = False
        for i in range(len(A)-1):
            if not((A[i] <= A[i+1] and inc) or (A[i] >= A[i+1] and dec)):
                dec, inc = inc, dec
                fin = True
                if fin and dec:
                    break
        if not(dec):
            return inc
        if not(inc):
            return dec
        return fin or True

